async function googleNoncePair(){const bytes=crypto.getRandomValues(new Uint8Array(32));const raw=btoa(String.fromCharCode(...bytes));const encoded=new TextEncoder().encode(raw);const digest=await crypto.subtle.digest('SHA-256',encoded);const hashed=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');return [raw,hashed]}
