const customerWorkLabels={scheduled:'Scheduled',on_my_way:'On my way',started:'In progress',completed:'Completed'};
function bookingDate(v){return v?new Date(v).toLocaleString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—'}
