async function submitBookingChange(){
  const btn=$('#submitBookingChange'),bookingId=$('#bookingChangeDialog').dataset.bookingId,reason=$('#bookingChangeReason').value.trim();let body={bookingId,reason};if(bookingChangeMode==='cancel'){if(!confirm('Send a cancellation request for this appointment? Your booking remains active until Namdar approves it.'))return;body.action='request_cancel'}else{const value=$('#bookingChangeSlot').value;if(!value){$('#bookingChangeStatus').textContent='Choose an available time window.';return}const [date,windowKey]=value.split('|');body={...body,action:'request_reschedule',date,windowKey}}
  setBusy(btn,true,'Sending request…');try{const d=await api('/api/customer-booking-changes',{method:'POST',body:JSON.stringify(body)});$('#bookingChangeStatus').textContent=d.message||'Request sent.';const {data:{session}}=await sb.auth.getSession();await loadPortal(session);setTimeout(()=>$('#bookingChangeDialog').close(),600)}catch(e){$('#bookingChangeStatus').textContent=e.message}finally{setBusy(btn,false)}
}
async function withdrawBookingChange(requestId,btn){
  if(!confirm('Withdraw this booking change request? Your existing appointment will stay unchanged.'))return;setBusy(btn,true,'Withdrawing…');try{await api('/api/customer-booking-changes',{method:'POST',body:JSON.stringify({action:'withdraw',requestId})});const {data:{session}}=await sb.auth.getSession();await loadPortal(session);$('#bookingChangeDialog')?.close()}catch(e){alert(e.message)}finally{setBusy(btn,false)}
}


async function downloadBillingDocument(kind,id,btn){const {data:{session}}=await sb.auth.getSession();if(!session)return;const key=kind==='receipt'?'payment_id':'invoice_id',label=btn?.textContent||'Download';if(btn){btn.disabled=true;btn.textContent='Preparing…'}try{const r=await fetch(`/api/billing-document?${key}=${encodeURIComponent(id)}`,{headers:{Authorization:`Bearer ${session.access_token}`}});if(!r.ok)throw new Error(await r.text()||'Could not download document.');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=kind==='receipt'?`Namdar-receipt-${String(id).slice(0,8)}.pdf`:`Namdar-invoice.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}catch(e){alert(e.message)}finally{if(btn){btn.disabled=false;btn.textContent=label}}}
async function payInvoice(bookingId,btn){setBusy(btn,true,'Opening secure payment…');try{const d=await api('/api/create-checkout',{method:'POST',body:JSON.stringify({bookingId})});location.href=d.url}catch(e){alert(e.message);setBusy(btn,false)}}
function renderBilling(rows,meta={}){const el=$('#accountBilling'),out=$('#billingOutstanding'),paid=$('#billingPaid'),count=$('#billingInvoiceCount');const active=(rows||[]).filter(i=>i.status!=='void'),outstanding=active.reduce((a,i)=>a+Number(i.outstanding||0),0),paidTotal=active.reduce((a,i)=>a+Number(i.amountPaid||0),0);if(out)out.textContent=money(outstanding);if(paid)paid.textContent=money(paidTotal);if(count)count.textContent=String(active.length);if(!el)return;if(!rows.length){el.innerHTML='<p>No invoices yet. Billing documents will appear when a booking is created.</p>';return}el.innerHTML=`<div class="billing-list">${rows.map(i=>{const due=i.dueAt?new Date(i.dueAt).toLocaleDateString('en-GB'):'—',payments=i.payments||[],canPay=meta.stripeEnabled&&Number(i.outstanding||0)>.004&&['issued','part_paid'].includes(i.status)&&i.booking?.status==='confirmed';return `<article class="billing-card"><div class="billing-card-head"><div><small>${esc(i.invoiceNumber||'Invoice')}</small><h3>${esc(i.serviceLabel||'Namdar service')}</h3><p>${i.booking?.startsAt?esc(bookingDate(i.booking.startsAt)):''}</p></div><span class="billing-status ${esc(i.status)}">${esc(prettyStatus(i.status))}</span></div><div class="billing-money-grid"><div><small>Total</small><strong>${money(i.total)}</strong></div><div><small>Paid</small><strong>${money(i.amountPaid)}</strong></div><div><small>Outstanding</small><strong>${money(i.outstanding)}</strong></div><div><small>Due</small><strong>${esc(due)}</strong></div></div><div class="account-actions"><button class="ghost-btn small" type="button" data-invoice-pdf="${i.id}">Download invoice PDF</button>${canPay?`<button class="primary-btn small" type="button" data-pay-invoice="${i.booking.id}">${Number(i.amountPaid||0)>0?'Pay balance':'Pay securely'}</button>`:''}</div>${payments.length?`<details class="billing-payments"><summary>Payment history (${payments.length})</summary><div>${payments.map(p=>`<div class="billing-payment-row"><div><strong>${p.direction==='refund'?'Refund':'Payment'} · ${money(p.amount)}</strong><small>${new Date(p.paidAt).toLocaleString('en-GB')} · ${esc(prettyStatus(p.method))}${p.reference?' · '+esc(p.reference):''}</small></div><button class="ghost-btn small" type="button" data-receipt-pdf="${p.id}">Receipt PDF</button></div>`).join('')}</div></details>`:''}</article>`}).join('')}</div>`;$$('[data-invoice-pdf]').forEach(b=>b.onclick=()=>downloadBillingDocument('invoice',b.dataset.invoicePdf,b));$$('[data-receipt-pdf]').forEach(b=>b.onclick=()=>downloadBillingDocument('receipt',b.dataset.receiptPdf,b));$$('[data-pay-invoice]').forEach(b=>b.onclick=()=>payInvoice(b.dataset.payInvoice,b))}
function renderSubscriptions(rows){const el=$('#accountSubscriptions');if(!el)return;el.innerHTML=rows.length?`<div class="portal-list">${rows.map(x=>`<div><div><b>${esc(names[x.service_key]||x.service_key)}</b><small>${esc(x.interval_key.replaceAll('_',' '))}${x.next_service_on?' · next '+new Date(x.next_service_on+'T12:00:00').toLocaleDateString('en-GB'):''}</small></div><span>${esc(x.status)} ${!['cancelled'].includes(x.status)?`<button class="ghost-btn small" data-cancel-sub="${x.id}">Cancel</button>`:''}</span></div>`).join('')}</div>`:'<p>No regular service subscriptions yet.</p>';$$('[data-cancel-sub]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this recurring service request/subscription?'))return;try{await api('/api/subscription',{method:'PATCH',body:JSON.stringify({id:b.dataset.cancelSub,action:'cancel'})});const {data:{session}}=await sb.auth.getSession();await loadPortal(session)}catch(e){alert(e.message)}})}
function imgs(urls,label){return Array.isArray(urls)&&urls.length?`<div class="project-image-grid">${urls.map(u=>`<img src="${esc(u)}" alt="${esc(label)}">`).join('')}</div>`:'<p class="muted">No images uploaded yet.</p>'}
function renderProjects(rows){$('#accountProjects').innerHTML=rows.length?rows.map(p=>`<article class="customer-project" data-project="${p.id}"><div class="project-head"><div><span class="status">${esc(p.status)}</span><h3>${esc(p.title)}</h3><p>${esc(names[p.service_key]||p.service_key||'Namdar project')} ${p.final_price!=null?'· '+money(p.final_price):''}</p></div>${p.tour_url?`<a class="primary-btn small" href="${esc(safeUrl(p.tour_url))}" target="_blank" rel="noopener">Open 3D tour</a>`:''}</div><div class="before-after"><div><h4>Before</h4>${imgs(p.before_images,'Before')}</div><div><h4>After</h4>${imgs(p.after_images,'After')}</div></div><div class="project-feedback"><label>Your comment<textarea data-comment rows="3">${esc(p.customer_comment||'')}</textarea></label><label>Rating<select data-rating><option value="">No rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${p.customer_rating===n?'selected':''}>${n} star${n===1?'':'s'}</option>`).join('')}</select></label><label class="consent"><input type="checkbox" data-share ${p.public_shared?'checked':''}><span>Enable a public share page.</span></label><div class="account-actions"><button class="primary-btn small" type="button" data-save-project="${p.id}">Save project settings</button>${p.public_shared?`<button class="ghost-btn" type="button" data-copy="${esc(SITE_ORIGIN+'/shared?project='+p.share_slug)}">Copy share link</button>`:''}</div></div></article>`).join(''):'<p>No projects published to your account yet.</p>';$$('[data-save-project]').forEach(b=>b.onclick=()=>saveProject(b.dataset.saveProject,b));$$('[data-copy]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied ✓'})}
async function saveProject(id,btn){const el=document.querySelector(`[data-project="${id}"]`);btn.disabled=true;try{await api('/api/customer-project-update',{method:'PATCH',body:JSON.stringify({id,customerComment:el.querySelector('[data-comment]').value.trim(),customerRating:el.querySelector('[data-rating]').value||null,publicShared:el.querySelector('[data-share]').checked})});const {data:{session}}=await sb.auth.getSession();await loadPortal(session)}catch(e){alert(e.message)}finally{btn.disabled=false}}
function renderTickets(tickets,msgs){const grouped={};for(const m of msgs){(grouped[m.ticket_id]??=[]).push(m)}$('#accountTickets').innerHTML=tickets.length?tickets.map(t=>`<article class="ticket-card"><div class="ticket-head"><div><strong>Ticket #${t.ticket_no}</strong><small>${esc(t.subject)} · ${esc(t.status.replaceAll('_',' '))}</small></div>${!['closed','cancelled'].includes(t.status)?`<button class="ghost-btn small" data-cancel-ticket="${t.id}">Cancel</button>`:''}</div><div class="ticket-thread">${(grouped[t.id]||[]).map(m=>`<div class="ticket-message ${esc(m.sender_role)}"><b>${m.sender_role==='staff'?'Namdar':m.sender_role==='assistant'?'Assistant':'You'}</b><p>${esc(m.message).replace(/\n/g,'<br>')}</p><small>${new Date(m.created_at).toLocaleString('en-GB')}</small></div>`).join('')}</div>${t.status==='awaiting_customer'?`<form class="ticket-reply-form" data-ticket="${t.id}"><textarea rows="3" placeholder="Reply to Namdar" required></textarea><button class="primary-btn small">Send reply</button></form>`:t.status==='awaiting_staff'?'<small>Waiting for Namdar to reply.</small>':''}</article>`).join(''):'<p>No support tickets yet.</p>';$$('.ticket-reply-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const ta=f.querySelector('textarea');try{await api('/api/ticket-reply',{method:'POST',body:JSON.stringify({ticketId:f.dataset.ticket,message:ta.value})});const {data:{session}}=await sb.auth.getSession();await loadPortal(session)}catch(err){alert(err.message)}});$$('[data-cancel-ticket]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this support ticket?'))return;try{await api('/api/ticket-action',{method:'PATCH',body:JSON.stringify({ticketId:b.dataset.cancelTicket,action:'cancel'})});const {data:{session}}=await sb.auth.getSession();await loadPortal(session)}catch(e){alert(e.message)}})}
function renderRewards(p,ledger,rewards,referrals){$('#rewardPoints').textContent=p.points_balance||0;$('#referralCode').textContent=p.referral_code||'—';$('#rewardList').innerHTML=rewards.length?`<div class="reward-grid">${rewards.map(r=>`<article class="reward-card"><h3>${esc(r.title)}</h3><p>${esc(r.description||'')}</p><strong>${r.points_cost} points</strong><button class="primary-btn small" data-redeem="${r.id}" ${Number(p.points_balance)<Number(r.points_cost)?'disabled':''}>Redeem</button></article>`).join('')}</div>`:'<p>No rewards are active yet.</p>';$('#loyaltyHistory').innerHTML=ledger.length?`<div class="portal-list">${ledger.map(x=>`<div><div><b>${esc(x.reason)}</b><small>${new Date(x.created_at).toLocaleDateString('en-GB')}</small></div><span class="${x.points>=0?'points-plus':'points-minus'}">${x.points>=0?'+':''}${x.points}</span></div>`).join('')}</div>`:'<p>No points activity yet.</p>';$('#referralList').innerHTML=referrals.length?`<div class="portal-list">${referrals.map(r=>`<div><div><b>${esc(r.referred_email||'Referral')}</b><small>${new Date(r.created_at).toLocaleDateString('en-GB')}</small></div><span>${esc(r.status)}${r.points_awarded?' · +'+r.points_awarded+' pts':''}</span></div>`).join('')}</div>`:'<p>No referrals yet. Share your personal link to start earning when referrals qualify.</p>';$$('[data-redeem]').forEach(b=>b.onclick=async()=>{if(!confirm('Redeem this reward using your points?'))return;try{const d=await api('/api/reward-redeem',{method:'POST',body:JSON.stringify({rewardId:b.dataset.redeem})});alert(`Reward issued. Code: ${d.redemption.redemption_code}`);const {data:{session}}=await sb.auth.getSession();await loadPortal(session)}catch(e){alert(e.message)}})}
function messageCategoryLabel(v=''){return({quote:'Quote',booking:'Booking',billing:'Billing',support:'Support',account:'Account',marketing:'Updates',general:'Namdar'})[v]||'Namdar'}
function messageCategoryIcon(v=''){return({quote:'Q',booking:'▣',billing:'£',support:'?',account:'N',marketing:'•',general:'N'})[v]||'N'}
function messageCategoryClass(v=''){return ['quote','booking','billing','support','account','marketing','general'].includes(v)?v:'general'}
function messageExcerpt(v='',limit=170){const t=String(v||'').replace(/\s+/g,' ').trim();return t.length>limit?t.slice(0,limit).trimEnd()+'…':t}
function messageRelativeTime(v){const t=new Date(v).getTime(),diff=t-Date.now(),abs=Math.abs(diff);if(!Number.isFinite(t))return'';const rtf=new Intl.RelativeTimeFormat('en-GB',{numeric:'auto'});if(abs<60000)return'just now';if(abs<3600000)return rtf.format(Math.round(diff/60000),'minute');if(abs<86400000)return rtf.format(Math.round(diff/3600000),'hour');if(abs<604800000)return rtf.format(Math.round(diff/86400000),'day');return new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}
function messageDateTime(v){try{return new Date(v).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})}catch{return''}}
function messageRowsForView(){return messageView==='archived'?archivedMessageCache:customerMessageCache}
function filteredCustomerMessages(){const q=messageSearch.trim().toLowerCase();return messageRowsForView().filter(m=>{if(messageFilter==='unread'&&m.readAt)return false;if(!['all','unread'].includes(messageFilter)&&m.category!==messageFilter)return false;if(q&&!`${m.subject||''} ${m.bodyText||''} ${messageCategoryLabel(m.category)}`.toLowerCase().includes(q))return false;return true})}
function syncMessageControls(){$$('[data-message-view]').forEach(b=>{const on=b.dataset.messageView===messageView;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});$$('[data-message-filter]').forEach(b=>{const on=b.dataset.messageFilter===messageFilter;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});const search=$('#messageSearch');if(search&&search.value!==messageSearch)search.value=messageSearch}
function renderCustomerMessages(){
  const inbox=customerMessageCache||[],unread=inbox.filter(x=>!x.readAt).length;
  $('#notificationBadge')?.classList.toggle('hidden',!unread);if($('#notificationBadge'))$('#notificationBadge').textContent=String(unread);
  $('#messagesTabBadge')?.classList.toggle('hidden',!unread);if($('#messagesTabBadge'))$('#messagesTabBadge').textContent=String(unread);
  const latest=inbox.find(x=>!x.readAt),bar=$('#accountNotificationBar');
  if(bar){bar.classList.toggle('hidden',!latest);bar.innerHTML=latest?`<div class="notification-bar-copy"><span class="message-category-icon ${messageCategoryClass(latest.category)}" aria-hidden="true">${esc(messageCategoryIcon(latest.category))}</span><div><small class="notification-kicker">${esc(messageCategoryLabel(latest.category))} · ${esc(messageRelativeTime(latest.sentAt))}</small><strong>${esc(latest.subject)}</strong><span>${esc(messageExcerpt(latest.bodyText,120))}</span></div></div><div class="admin-actions"><button class="primary-btn small" type="button" data-open-notification="${esc(latest.id)}">Open</button><button class="ghost-btn small" type="button" data-read-notification="${esc(latest.id)}">Mark read</button></div>`:''}
  const pop=$('#notificationPopoverList');
  const popItems=notificationPopoverFilter==='all'?inbox:inbox.filter(m=>messageCategoryClass(m.category)===notificationPopoverFilter);
  const emptyPopoverLabel=notificationPopoverFilter==='all'?'new notifications':notificationPopoverFilter+' notifications';
  if(pop)pop.innerHTML=popItems.length?popItems.slice(0,10).map(m=>`<button type="button" class="notification-popover-item ${m.readAt?'':'unread'}" data-pop-message="${esc(m.id)}"><span class="message-category-icon ${messageCategoryClass(m.category)}" aria-hidden="true">${esc(messageCategoryIcon(m.category))}</span><span class="notification-popover-copy"><strong>${esc(m.subject)}</strong><small>${esc(messageExcerpt(m.bodyText,96))}</small><span class="notification-popover-meta">${esc(messageCategoryLabel(m.category))} · ${esc(messageRelativeTime(m.sentAt))}</span></span>${m.readAt?'':'<i class="unread-dot" aria-label="Unread"></i>'}</button>`).join(''):`<div class="notification-empty-state"><span aria-hidden="true">✓</span><strong>You’re all caught up</strong><small>No ${esc(emptyPopoverLabel)} here.</small></div>`;
  syncMessageControls();
  const rows=filteredCustomerMessages(),all=messageRowsForView(),visibleUnread=rows.filter(x=>!x.readAt).length;
  if($('#messageSummary'))$('#messageSummary').textContent=`${all.length} ${messageView==='archived'?'archived':'in inbox'} · ${inbox.filter(x=>!x.readAt).length} unread`;
  const clear=$('#messageSearchClear');if(clear)clear.classList.toggle('hidden',!messageSearch);
  const list=$('#accountMessages');
  if(list){
    if(!rows.length){const filtered=messageSearch||messageFilter!=='all';list.innerHTML=`<div class="notification-center-empty"><span aria-hidden="true">${messageView==='archived'?'↶':'✓'}</span><h3>${filtered?'No matching notifications':messageView==='archived'?'Archive is empty':'You’re all caught up'}</h3><p>${filtered?'Try another search or filter.':messageView==='archived'?'Archived notifications will stay here until you restore them.':'Quote, booking, billing and support updates will appear here automatically.'}</p></div>`}
    else list.innerHTML=`<div class="customer-message-list">${rows.map(m=>{const expanded=expandedMessageIds.has(m.id),longBody=String(m.bodyText||'').trim().length>190||String(m.bodyText||'').includes('\n');return `<article class="customer-message-card ${m.readAt?'':'unread'}" data-message-card="${esc(m.id)}"><div class="customer-message-head"><div class="message-title-row"><span class="message-category-icon ${messageCategoryClass(m.category)}" aria-hidden="true">${esc(messageCategoryIcon(m.category))}</span><div><span class="message-category-label">${esc(messageCategoryLabel(m.category))}</span><h3>${esc(m.subject)}</h3><small>${esc(messageDateTime(m.sentAt))}${m.deliveryStatus==='skipped'?' · In-app copy':''}</small></div></div>${m.readAt?'':'<b>New</b>'}</div><p class="message-preview ${expanded?'hidden':''}">${esc(messageExcerpt(m.bodyText,190))}</p><div class="customer-message-body ${expanded?'':'hidden'}">${esc(m.bodyText||'').replace(/\n/g,'<br>')}</div><div class="account-actions message-actions">${m.targetPath?`<button class="primary-btn small" type="button" data-message-target="${esc(m.id)}">Open related item</button>`:''}${longBody?`<button class="ghost-btn small" type="button" data-message-expand="${esc(m.id)}">${expanded?'Hide message':'Read message'}</button>`:''}<button class="ghost-btn small" type="button" data-message-read="${esc(m.id)}" data-message-read-action="${m.readAt?'unread':'read'}">${m.readAt?'Mark unread':'Mark read'}</button><button class="text-action" type="button" data-message-${messageView==='archived'?'restore':'archive'}="${esc(m.id)}">${messageView==='archived'?'Restore':'Archive'}</button></div></article>`}).join('')}</div>`
  }
  $$('[data-open-notification],[data-pop-message],[data-message-target]').forEach(b=>b.onclick=()=>openCustomerMessage(b.dataset.openNotification||b.dataset.popMessage||b.dataset.messageTarget));
  $$('[data-read-notification]').forEach(b=>b.onclick=()=>markCustomerMessage(b.dataset.readNotification,'read'));
  $$('[data-message-read]').forEach(b=>b.onclick=()=>markCustomerMessage(b.dataset.messageRead,b.dataset.messageReadAction||'read'));
  $$('[data-message-archive]').forEach(b=>b.onclick=()=>markCustomerMessage(b.dataset.messageArchive,'archive'));
  $$('[data-message-restore]').forEach(b=>b.onclick=()=>markCustomerMessage(b.dataset.messageRestore,'restore'));
  $$('[data-message-expand]').forEach(b=>b.onclick=()=>{const id=b.dataset.messageExpand;expandedMessageIds.has(id)?expandedMessageIds.delete(id):expandedMessageIds.add(id);renderCustomerMessages()});
}
async function loadCustomerMessages({silent=false,view='inbox'}={}){try{const archived=view==='archived',d=await api(`/api/customer-messages?view=${archived?'archived':'inbox'}`,{method:'GET'});if(archived){archivedMessageCache=d.messages||[];archivedMessagesLoaded=true}else customerMessageCache=d.messages||[];renderCustomerMessages();return d}catch(e){if(!silent&&$('#accountMessages'))$('#accountMessages').innerHTML=`<p>${esc(e.message)}</p>`;return{messages:[],unreadCount:0}}}
async function setMessageView(view){messageView=view==='archived'?'archived':'inbox';messageFilter='all';messageSearch='';if(messageView==='archived'&&!archivedMessagesLoaded)await loadCustomerMessages({silent:true,view:'archived'});else renderCustomerMessages()}
async function markCustomerMessage(id,action='read'){try{await api('/api/customer-messages',{method:'PATCH',body:JSON.stringify({messageId:id,action})});if(action==='archive'||action==='restore')archivedMessagesLoaded=false;await loadCustomerMessages({silent:true,view:'inbox'});if(messageView==='archived')await loadCustomerMessages({silent:true,view:'archived'})}catch(e){alert(e.message)}}
async function markAllCustomerMessages(){try{await api('/api/customer-messages',{method:'PATCH',body:JSON.stringify({action:'read_all'})});await loadCustomerMessages({silent:true,view:'inbox'});if(messageView==='archived')renderCustomerMessages()}catch(e){alert(e.message)}}
async function openCustomerMessage(id){let m=customerMessageCache.find(x=>x.id===id)||archivedMessageCache.find(x=>x.id===id);if(!m)return;if(!m.readAt)await markCustomerMessage(id,'read');$('#notificationPopover')?.classList.add('hidden');$('#notificationBell')?.setAttribute('aria-expanded','false');if(m.targetPath&&m.targetPath.startsWith('/account')){const u=new URL(m.targetPath,SITE_ORIGIN);history.replaceState({},'',u.pathname+u.search+u.hash);applyAccountDestination()}else{showPortalPanel('messagesPanel',{updateUrl:true});if(messageView==='archived')await setMessageView('inbox');expandedMessageIds.add(id);renderCustomerMessages();const el=document.querySelector(`[data-message-card="${CSS.escape(id)}"]`);el?.scrollIntoView({behavior:'smooth',block:'center'})}}
async function renderMfa(){if(!sb)return;const {data,error}=await sb.auth.mfa.listFactors();if(error){$('#mfaStatus').textContent=error.message;return}const factors=data?.all||[...(data?.totp||[]),...(data?.phone||[])];const verified=factors.filter(x=>x.status==='verified');$('#mfaStatus').innerHTML=verified.length?verified.map(x=>`<div class="mfa-factor"><span>✓ ${esc(x.friendly_name||x.factor_type||'MFA factor')}</span><button class="ghost-btn small" data-remove-mfa="${x.id}">Disable</button></div>`).join(''):'<p>MFA is currently off.</p>';$$('[data-remove-mfa]').forEach(b=>b.onclick=async()=>{if(!confirm('Disable this MFA factor? You will be asked for a current authenticator code.'))return;const code=prompt('Enter the current authenticator code to disable MFA:');if(!code)return;const {error:verifyError}=await sb.auth.mfa.challengeAndVerify({factorId:b.dataset.removeMfa,code:String(code).trim()});if(verifyError){alert(verifyError.message);return}const {error:removeError}=await sb.auth.mfa.unenroll({factorId:b.dataset.removeMfa});if(removeError)alert(removeError.message);await renderMfa()})}
async function copyReferral(){if(!profileCache?.referral_code)return;const url=`${SITE_ORIGIN}/account?ref=${encodeURIComponent(profileCache.referral_code)}`;await navigator.clipboard.writeText(url);alert('Referral link copied.')}
$('#showLogin').onclick=()=>switchAuth(false);$('#showRegister').onclick=()=>switchAuth(true);
$$('[data-toggle-password]').forEach(b=>b.onclick=()=>{const input=$('#'+b.dataset.togglePassword),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password')});
